import Contact from "./Component/Contact";
import IntroLoader from "./Component/IntroLoader";
import ScrollNavbar from "./Component/ScrollNavbar";
import Slide, { type SlideData } from "./Component/Slide";
import slides from "./data/slides.generated.json";

// Slide order and alt text live in app/data/slides.json.
// Images are generated by scripts/optimize-images.mjs (runs before dev/build).
export default function Home() {
  return (
    <>
      <IntroLoader />
      <ScrollNavbar />

      <main className="w-full bg-white">
        {(slides as SlideData[]).map((slide, i) => (
          <section key={slide.name}>
            <Slide slide={slide} priority={i === 0} />
          </section>
        ))}

        <Contact />
      </main>
    </>
  );
}
